defmodule AshPhoenixStarter.Farms.FarmLaborAssignment do
  use Ash.Resource,
    domain: Elixir.AshPhoenixStarter.Farms,
    data_layer: AshPostgres.DataLayer

  postgres do
    table "farm_labor_assignments"
  end

  multitenancy do
    strategy :context
  end

  preparations do
    prepare AshPhoenixStarter.Preparations.SetTenant
  end

  changes do
    change AshPhoenixStarter.Changes.SetTenant
  end

  attributes do
    # Primary Key generated by Postgres via uuid_generate_v7()
    uuid_primary_key :id do
      generated? true
      allow_nil? true
      writable? false
    end

    attribute :assignment_date, :date do
      allow_nil? false
      public? true
    end

    attribute :hours_worked, :float do
      allow_nil? false
      public? true
    end

    attribute :task_description, :string do
      allow_nil? true
      public? true
    end

    attribute :cost, :decimal do
      allow_nil? true
      public? true
    end

    # Database-managed timestamps
    attribute :inserted_at, :utc_datetime_usec do
      generated? true
      allow_nil? true
      writable? false
    end

    attribute :updated_at, :utc_datetime_usec do
      generated? true
      allow_nil? true
      writable? false
    end
  end

  relationships do
    # CHANGED: Now references FarmInputApplication instead of Employee
    belongs_to :employee, AshPhoenixStarter.Farms.FarmInputApplication do
      attribute_type :uuid
      allow_nil? false
      public? true
    end

    belongs_to :planting, AshPhoenixStarter.Farms.FarmPlanting do
      attribute_type :uuid
      allow_nil? true
      public? true
    end

    # CHANGED: Adjusted to match your structural FarmField resource module name
    belongs_to :field, AshPhoenixStarter.Farms.FarmField do
      attribute_type :uuid
      allow_nil? true
      public? true
    end
  end

  actions do
    defaults [:read, :destroy]

    create :create do
      primary? true
      accept [
        :assignment_date,
        :hours_worked,
        :task_description,
        :cost,
        :employee_id,
        :planting_id,
        :field_id
      ]
    end

    update :update do
      primary? true
      accept [
        :assignment_date,
        :hours_worked,
        :task_description,
        :cost,
        :employee_id,
        :planting_id,
        :field_id
      ]
    end
  end
end
